node -v && cat > /tmp/check.mjs <<'EOF'
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/ours-g2-1/bot.mjs";
import assert from "node:assert";
const u = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const g = createPushGate();
// Tokyo 12:00 = 03:00Z
const at = (iso) => new Date(iso);
assert.deepEqual(g.attempt(u, at("2026-10-22T03:00:00Z")), { allowed: true, reason: null });
// 22:00 Tokyo = 13:00Z quiet start included; 06:59 quiet; 07:00 not quiet
assert.equal(g.attempt(u, at("2026-10-22T13:00:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(u, at("2026-10-21T21:59:00Z")).reason, "quiet_hours");
assert.equal(g.attempt({ ...u, id: "b" }, at("2026-10-21T22:00:00Z")).allowed, true);
// cap
assert.equal(g.attempt(u, at("2026-10-22T04:00:00Z")).allowed, true);
assert.equal(g.attempt(u, at("2026-10-22T05:00:00Z")).allowed, true);
assert.equal(g.attempt(u, at("2026-10-22T06:00:00Z")).reason, "daily_cap_reached");
// next local day (Tokyo 00:00 is quiet; 07:00 Tokyo = 22:00Z)
assert.equal(g.attempt(u, at("2026-10-22T22:00:00Z")).allowed, true);
// day is local, not UTC: LA user, 23:30 local vs 00:30 local next day
const la = { id: "la", timeZone: "America/Los_Angeles", quietStart: "00:00", quietEnd: "00:00", dailyCap: 1 };
assert.equal(g.attempt(la, at("2026-10-22T06:30:00Z")).allowed, true); // Oct 21 23:30 PDT
assert.equal(g.attempt(la, at("2026-10-22T07:30:00Z")).allowed, true); // Oct 22 00:30 PDT
assert.equal(g.attempt(la, at("2026-10-22T08:30:00Z")).reason, "daily_cap_reached");
// invalid zone, independent gates
assert.equal(g.attempt({ ...u, timeZone: "Mars/Base" }, at("2026-10-22T03:00:00Z")).reason, "invalid_time_zone");
assert.equal(createPushGate().attempt(u, at("2026-10-22T03:00:00Z")).allowed, true);
console.log("ok");
EOF
